import { test, expect, type APIRequestContext } from '@playwright/test';

function makeEmail(prefix: string): string {
  const rand = Math.random().toString(36).slice(2, 7);
  return `${prefix}-${Date.now()}-${rand}@example.com`;
}

async function loginUser(
  request: APIRequestContext,
  email: string,
  nickname: string
): Promise<{ id: string; email: string; nickname: string }> {
  const sendRes = await request.post('/api/auth/send-code', { data: { email } });
  expect(sendRes.status()).toBe(200);
  const sendJson = await sendRes.json();
  const verifyRes = await request.post('/api/auth/verify-code', {
    data: { email, code: sendJson.devCode, nickname },
  });
  expect(verifyRes.status()).toBe(200);
  return (await verifyRes.json()).user;
}

test.describe.serial('动态改版初版 E2E 校验套件', () => {
  test('1. 列表形态展示、点击统计、收藏与分享链接直达', async ({ page, browser }) => {
    await page.setViewportSize({ width: 1440, height: 900 });
    const user = await loginUser(page.request, makeEmail('feed-revamp'), '内容创作者');

    const title1 = `列表动态一-${Date.now()}`;
    const title2 = `列表动态二-${Date.now()}`;
    const tag = `热议话题${Date.now().toString().slice(-4)}`;

    const p1 = await (await page.request.post('/api/posts', {
      data: { title: title1, content: '第一条 X.com 风格动态正文内容', tags: [tag] },
    })).json();
    await page.request.post('/api/posts', {
      data: { title: title2, content: '第二条动态用于校验单列纵向排列', tags: [tag] },
    });
    const postId = p1.post.id as string;

    await page.goto('/');
    const card1 = page.locator('article').filter({ hasText: title1 }).first();
    const card2 = page.locator('article').filter({ hasText: title2 }).first();
    await expect(card1).toBeVisible({ timeout: 10000 });
    await expect(card2).toBeVisible({ timeout: 10000 });

    const box1 = await card1.boundingBox();
    const box2 = await card2.boundingBox();
    expect(box1 && box2).toBeTruthy();
    if (box1 && box2) {
      expect(Math.abs(box1.x - box2.x)).toBeLessThanOrEqual(24);
    }

    // 收藏切换
    const bookmarkBtn = card1.getByRole('button', { name: /收藏/i }).first();
    await expect(bookmarkBtn).toBeVisible();
    const bookmarkResp = page.waitForResponse(
      (r) => r.url().includes(`/api/posts/${postId}/bookmark`) && r.request().method() === 'POST'
    );
    await bookmarkBtn.click();
    expect((await bookmarkResp).status()).toBe(200);

    // 分享计数与直达链接
    const shareBtn = card1.getByRole('button', { name: /分享/i }).first();
    await expect(shareBtn).toBeVisible();
    const shareResp = page.waitForResponse(
      (r) => r.url().includes(`/api/posts/${postId}/share`) && r.request().method() === 'POST'
    );
    await shareBtn.click();
    expect((await shareResp).status()).toBe(200);

    // 访客通过分享 URL 直达动态详情并累加点击数
    const anonCtx = await browser.newContext();
    try {
      const anonPage = await anonCtx.newPage();
      await anonPage.goto(`/posts/${postId}`);
      await expect(anonPage.getByText(title1).first()).toBeVisible({ timeout: 10000 });
      await expect
        .poll(async () => (await (await page.request.get(`/api/posts/${postId}`)).json()).post.viewsCount)
        .toBeGreaterThanOrEqual(1);
    } finally {
      await anonCtx.close();
    }

    // 个人主页收藏列表包含该动态
    const bmAct = await (await page.request.get(`/api/users/${user.id}/activity?tab=bookmarks`)).json();
    expect(bmAct.items.some((p: { id: string }) => p.id === postId)).toBe(true);
  });

  test('2. 右侧热门话题与推荐关注展示及互动', async ({ page, browser }) => {
    await page.setViewportSize({ width: 1440, height: 900 });
    const ctxCreator = await browser.newContext();
    try {
      const creatorNick = `推荐博主${Date.now().toString().slice(-4)}`;
      await loginUser(ctxCreator.request, makeEmail('rec-creator'), creatorNick);
      const hotTag = `精选趋势${Date.now().toString().slice(-4)}`;
      await ctxCreator.request.post('/api/posts', {
        data: { title: `趋势内容-${Date.now()}`, content: '用于生成热门话题', tags: [hotTag] },
      });

      await loginUser(page.request, makeEmail('rec-viewer'), '浏览者');
      await page.goto('/');

      await expect(page.getByText(/热门话题/).first()).toBeVisible({ timeout: 10000 });
      await expect(page.getByText(/推荐关注/).first()).toBeVisible({ timeout: 10000 });
      await expect(page.getByText(hotTag).first()).toBeVisible({ timeout: 10000 });
    } finally {
      await ctxCreator.close();
    }
  });

  test('3. 多账号登录与一键切换', async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 900 });
    const nickA = `主号A${Date.now().toString().slice(-4)}`;
    const nickB = `副号B${Date.now().toString().slice(-4)}`;
    const userA = await loginUser(page.request, makeEmail('multi-a'), nickA);
    const userB = await loginUser(page.request, makeEmail('multi-b'), nickB);

    const accountsJson = await (await page.request.get('/api/auth/accounts')).json();
    expect(accountsJson.activeUserId).toBe(userB.id);
    expect(accountsJson.accounts.length).toBeGreaterThanOrEqual(2);

    await page.goto('/');
    const sidebar = page.locator('aside').first();
    const trigger = sidebar.getByRole('button', { name: new RegExp(`${nickB}|个人资料|账号`, 'i') }).last();
    await expect(trigger).toBeVisible({ timeout: 10000 });
    await trigger.click();

    const switchTarget = page.getByRole('menuitem', { name: new RegExp(nickA) }).or(page.getByRole('button', { name: new RegExp(nickA) })).first();
    await expect(switchTarget).toBeVisible({ timeout: 10000 });
    const switchResp = page.waitForResponse(
      (r) => r.url().includes('/api/auth/switch') && r.request().method() === 'POST'
    );
    await switchTarget.click();
    expect((await switchResp).status()).toBe(200);

    const meAfter = await (await page.request.get('/api/auth/me')).json();
    expect(meAfter.user.id).toBe(userA.id);
  });
});
